function stopScanner(){if(scannerTimer)cancelAnimationFrame(scannerTimer);scannerTimer=null;scannerStream?.getTracks().forEach(track=>track.stop());scannerStream=null;$('#scannerVideo').srcObject=null;if($('#scannerDialog').open)$('#scannerDialog').close()}
async function startScanner(){const dialog=$('#scannerDialog');dialog.showModal();$('#manualQr').classList.add('hidden');$('#scannerVideo').classList.remove('hidden');if(!('BarcodeDetector'in window)){showManualScanner('Kamera-skanning støttes ikke i denne nettleseren.');return}try{scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});const video=$('#scannerVideo');video.srcObject=scannerStream;await video.play();const detector=new BarcodeDetector({formats:['qr_code']});const detect=async()=>{if(!scannerStream)return;try{const codes=await detector.detect(video);if(codes[0]?.rawValue){stopScanner();await clockWithQr(codes[0].rawValue);return}}catch{}scannerTimer=requestAnimationFrame(detect)};detect()}catch{showManualScanner('Kameraet kunne ikke åpnes. Du kan skrive inn innholdet fra QR-koden.') }}
function showManualScanner(message){$('#scannerHelp').textContent=message;$('#scannerVideo').classList.add('hidden');$('#manualQr').classList.remove('hidden')}
function getPosition(){return new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,()=>reject(new Error('Posisjonen kunne ikke hentes. Tillat posisjonstilgang og prøv igjen.')),{enableHighAccuracy:true,timeout:15000,maximumAge:0}))}
async function clockWithQr(qrToken){const button=$('#scanClock');button.disabled=true;button.textContent='Kontrollerer posisjon …';try{const position=await getPosition();const action=clockState?.open_entry?'clock_out':'clock_in';const data=await authenticated('/functions/v1/time-clock',{method:'POST',body:{action,qr_token:qrToken,latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy:position.coords.accuracy}});show(action==='clock_in'?`Stemplet inn ${formatTime(data.entry.started_at)}.`:`Stemplet ut ${formatTime(data.entry.ended_at)}.`);await loadClock()}catch(error){show(error.message)}finally{button.disabled=false;renderClock()}}
