function localDate(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Oslo'}).format(new Date())}
function dateTimeLocal(value){const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value)).reduce((o,p)=>(o[p.type]=p.value,o),{});return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`}
function osloWallToIso(value){const [date,time]=value.split('T'),[year,month,day]=date.split('-').map(Number),[hour,minute]=time.split(':').map(Number),wanted=Date.UTC(year,month-1,day,hour,minute);let guess=wanted;for(let i=0;i<3;i++){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(guess)).reduce((o,x)=>(o[x.type]=Number(x.value)||x.value,o),{});const shown=Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute);guess+=wanted-shown}return new Date(guess).toISOString()}
function approvalSource(value){return({qr:'QR-kode',manual:'Manuell',automatic:'Automatisk'})[value]||value}
function rosterDelta(value){if(value===null||value===undefined)return null;if(value===0)return '0 min';return `${value>0?'+':'−'}${Math.abs(value)} min`}
function rosterDeviationHtml(entry){const match=entry.roster_match;if(!match)return '<span class="muted">–</span>';if(match.status==='unplanned')return '<div class="roster-deviation warning"><strong>Ikke planlagt</strong><small>Ingen vakt i publisert vaktliste</small></div>';const planned=`${rosterTime(match.planned.start_time)}–${rosterTime(match.planned.end_time)}`;if(match.status==='match')return `<div class="roster-deviation ok"><strong>Plan ${planned}</strong><small>Som planlagt</small></div>`;const parts=[`Inn ${rosterDelta(match.start_delta_minutes)}`,match.end_delta_minutes===null?'Ut pågår':`ut ${rosterDelta(match.end_delta_minutes)}`];return `<div class="roster-deviation warning"><strong>Plan ${planned}</strong><small>${parts.join(' · ')}</small></div>`}
async function loadApproval(){const month=$('#approvalMonth').value,employeeId=$('#approvalEmployee').value;if(!month||!employeeId){show('Velg måned og ansatt.');return}const button=$('#loadApproval');button.disabled=true;button.textContent='Henter …';try{approvalData=await authenticated('/functions/v1/time-review-admin',{method:'POST',body:{action:'load',month,employee_id:employeeId}});renderApproval()}catch(error){show(error.message)}finally{button.disabled=false;button.textContent='Hent timer'}}
async function loadMonthOverview(){const month=$('#approvalMonth').value;if(!month)return;monthOverview=await authenticated('/functions/v1/time-review-admin',{method:'POST',body:{action:'overview',month}});renderMonthOverview()}
function renderMonthOverview(){const locked=monthOverview.status==='locked',rows=monthOverview.employees||[],ready=rows.length>0&&rows.every(x=>x.status==='approved'&&x.open_entries===0);$('#monthLockStatus').textContent=locked?`Låst · revisjon ${monthOverview.revision}`:ready?'Klar for låsing':'Ikke klar for låsing';$('#monthLockMessage').textContent=locked?`Låst ${new Date(monthOverview.locked_at).toLocaleString('nb-NO',{timeZone:'Europe/Oslo'})}. Rapportgrunnlaget kan ikke endres.`:rows.length?`${rows.filter(x=>x.status==='approved').length} av ${rows.length} ansatte er godkjent.`:'Ingen registreringer i denne måneden.';const button=$('#lockMonth');button.classList.toggle('hidden',locked);button.disabled=!ready;$('#monthApprovalRows').innerHTML=rows.length?`<table><thead><tr><th>Ansatt</th><th>Registreringer</th><th>Timer</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${escapeHtml(x.employee_number)} · ${escapeHtml(x.full_name)}</strong></td><td>${x.entries}${x.open_entries?` · ${x.open_entries} åpne`:''}</td><td>${hours(x.hours)}</td><td><span class="status ${x.status==='approved'||x.status==='locked'?'active':''}">${x.status==='locked'?'Låst':x.status==='approved'?'Godkjent':'Åpen'}</span></td><td><button class="small" data-review-employee="${x.id}">Vis timer</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Ingen registreringer i denne måneden.</div>'}
function renderApproval(){const locked=approvalData.status==='locked',approved=approvalData.status==='approved',entries=approvalData.entries||[],open=entries.some(e=>!e.ended_at);$('#approvalStatus').textContent=locked?'Låst':approved?'Godkjent':'Åpen';$('#approvalMessage').textContent=locked?'Måneden er låst og kan ikke endres.':approved?'Måneden er godkjent. En korrigering åpner godkjenningen på nytt.':open?'En åpen registrering må stemples ut før måneden kan godkjennes.':'Klar for kontroll og godkjenning.';$('#approvalHours').textContent=hours(entries.reduce((s,e)=>s+durationHours(e),0));$('#approvalEmpty').classList.toggle('hidden',entries.length>0);$('#approvalRows').innerHTML=entries.map(e=>`<tr class="${e.roster_match?.status==='deviation'||e.roster_match?.status==='unplanned'?'time-deviation-row':''}"><td>${formatDay(e.started_at)}</td><td>${formatTime(e.started_at)}</td><td>${e.ended_at?formatTime(e.ended_at):'<span class="status">Pågår</span>'}</td><td>${e.ended_at?hours(durationHours(e)):'–'}</td><td>${rosterDeviationHtml(e)}</td><td>${approvalSource(e.source)}${e.auto_clocked_out?' · automatisk ut':''}</td><td>${!locked&&e.ended_at?`<button class="small" data-time-edit="${e.id}">Rediger</button>`:''}</td></tr>`).join('');const approve=$('#approveMonth');approve.disabled=locked||open;approve.classList.toggle('hidden',locked);approve.textContent=approved?'Godkjenn på nytt':'Godkjenn måned';$('#approvalResult').classList.remove('hidden')}
