function currentIsoWeek(){const d=new Date(`${localDate()}T12:00:00Z`),day=d.getUTCDay()||7;d.setUTCDate(d.getUTCDate()+4-day);const yearStart=new Date(Date.UTC(d.getUTCFullYear(),0,1)),week=Math.ceil((((d-yearStart)/86400000)+1)/7);return `${d.getUTCFullYear()}-W${String(week).padStart(2,'0')}`}
function reportRange(){if($('#summaryPeriod').value==='month'){const [year,month]=$('#summaryMonth').value.split('-').map(Number),last=new Date(Date.UTC(year,month,0)).getUTCDate();return{from:`${year}-${String(month).padStart(2,'0')}-01`,to:`${year}-${String(month).padStart(2,'0')}-${last}`}}const [year,week]=$('#summaryWeek').value.split('-W').map(Number),jan4=new Date(Date.UTC(year,0,4)),monday=new Date(jan4);monday.setUTCDate(jan4.getUTCDate()-(jan4.getUTCDay()||7)+1+(week-1)*7);const sunday=new Date(monday);sunday.setUTCDate(monday.getUTCDate()+6);return{from:monday.toISOString().slice(0,10),to:sunday.toISOString().slice(0,10)}}
function reportHours(entry){return entry.ended_at?Math.max(0,(new Date(entry.ended_at)-new Date(entry.started_at))/3600000):0}
function reportRow(employee,data){const entries=data.entries.filter(e=>e.employee_id===employee.id),adjustments=data.adjustments.filter(a=>a.employee_id===employee.id);return{employee,ordinary:entries.filter(e=>e.kind==='work').reduce((s,e)=>s+reportHours(e),0),sick:entries.filter(e=>e.kind==='sick_pay').reduce((s,e)=>s+reportHours(e),0)+adjustments.filter(a=>a.category==='sick_pay').reduce((s,a)=>s+Number(a.hours),0),o40:adjustments.filter(a=>a.category==='overtime_40').reduce((s,a)=>s+Number(a.hours),0),o100:adjustments.filter(a=>a.category==='overtime_100').reduce((s,a)=>s+Number(a.hours),0),open:entries.filter(e=>!e.ended_at).length,manual:entries.filter(e=>e.source==='manual').length,entries}}
function renderSummaryReport(data){const rows=data.employees.map(e=>reportRow(e,data)),sum=key=>rows.reduce((s,r)=>s+r[key],0);$('#summaryReportTitle').textContent=`${data.from}–${data.to} · ${rows.length===1?rows[0].employee.full_name:'Alle ansatte'}`;$('#summaryReportRows').innerHTML=rows.map(r=>`<tr><td><strong>${escapeHtml(r.employee.employee_number)} · ${escapeHtml(r.employee.full_name)}</strong></td><td>${hours(r.ordinary)}</td><td>${hours(r.o40)}</td><td>${hours(r.o100)}</td><td>${hours(r.sick)}</td><td>${r.open}</td><td>${r.manual}</td></tr>`).join('');$('#summaryReportTotal').innerHTML=rows.length>1?`<tr><th>Totalt</th><th>${hours(sum('ordinary'))}</th><th>${hours(sum('o40'))}</th><th>${hours(sum('o100'))}</th><th>${hours(sum('sick'))}</th><th>${sum('open')}</th><th>${sum('manual')}</th></tr>`:'';const detail=$('#summaryDetails');if(rows.length===1){detail.classList.remove('hidden');detail.innerHTML='<h3>Registreringer dag for dag</h3>'+((rows[0].entries.length?rows[0].entries.map(e=>`<div class="time-row"><span><strong>${formatDay(e.started_at)}</strong><small>${formatTime(e.started_at)}–${e.ended_at?formatTime(e.ended_at):'Pågår'} · ${e.source==='manual'?'Manuell':'QR'}</small></span><strong>${e.ended_at?hours(reportHours(e)):'Åpen'}</strong></div>`).join(''):'<p class="muted">Ingen registreringer i perioden.</p>'))}else{detail.classList.add('hidden');detail.innerHTML=''}$('#summaryReportResult').classList.remove('hidden')}
$('#summaryWeek').value=currentIsoWeek();$('#summaryMonth').value=localMonth();
