$('#adminHmsDeviations').onclick=async event=>{const button=event.target.closest('[data-hms-save]');if(!button)return;const id=button.dataset.hmsSave;button.disabled=true;try{await authenticated('/functions/v1/hms',{method:'PATCH',body:{action:'handle_deviation',id,status:document.querySelector(`[data-hms-status="${id}"]`).value,admin_comment:document.querySelector(`[data-hms-comment="${id}"]`).value.trim()}});show('Avviket er oppdatert.');await loadHms()}catch(error){show(error.message)}finally{button.disabled=false}};

const sickTypeText=value=>({self_certification:'Egenmelding',medical_certificate:'Sykmelding fra lege',sick_child:'Sykt barn'})[value]||value;
const sickStatusText=value=>({pending:'Til behandling',approved:'Godkjent',rejected:'Avvist'})[value]||value;
const displayDate=value=>new Date(`${value}T12:00:00Z`).toLocaleDateString('nb-NO');
function monthRange(){const month=localMonth(),[year,m]=month.split('-').map(Number);return{from:`${month}-01`,to:`${month}-${String(new Date(Date.UTC(year,m,0)).getUTCDate()).padStart(2,'0')}`}}
async function loadSickLeave(adminView=false){let path='/functions/v1/sick-leave';if(adminView){const from=$('#sickStatsFrom').value,to=$('#sickStatsTo').value;path+=`?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`}sickLeaveData=await authenticated(path);renderSickLeave()}
function sickRequestHtml(r,adminView=false){const employee=r.employees||{},period=r.start_date===r.end_date?displayDate(r.start_date):`${displayDate(r.start_date)}–${displayDate(r.end_date)}`;return `<article class="sick-request"><div class="sick-request-head"><div><strong>${adminView?`${escapeHtml(employee.employee_number||'')} · ${escapeHtml(employee.full_name||'')}`:sickTypeText(r.absence_type)}</strong><p>${adminView?sickTypeText(r.absence_type)+' · ':''}${period}</p>${r.employee_note?`<p class="muted">${escapeHtml(r.employee_note)}</p>`:''}${r.admin_comment?`<p class="muted">Kommentar: ${escapeHtml(r.admin_comment)}</p>`:''}</div><span class="status ${r.status}">${sickStatusText(r.status)}</span></div>${adminView&&r.status==='pending'?`<div class="sick-actions"><label>Kommentar<textarea data-sick-comment="${r.id}" rows="2" placeholder="Påkrevd ved avvisning"></textarea></label><button class="secondary" data-sick-handle="${r.id}" data-status="rejected">Avvis</button><button class="primary" data-sick-handle="${r.id}" data-status="approved">Godkjenn</button></div>`:''}</article>`}
function renderSickLeave(){if(currentEmployee?.role==='admin'){const stats=sickLeaveData.statistics||{};$('#sickStats').innerHTML=`<div><span>Sykefravær</span><strong>${Number(stats.absence_percentage||0).toLocaleString('nb-NO',{maximumFractionDigits:2})} %</strong></div><div><span>Godkjente timer</span><strong>${hours(stats.sick_hours)}</strong></div><div><span>Forventede timer</span><strong>${hours(stats.expected_hours)}</strong></div>`;const requests=sickLeaveData.requests||[];$('#adminSickRequests').innerHTML=requests.length?requests.map(r=>sickRequestHtml(r,true)).join(''):'<p class="muted">Ingen fraværsmeldinger i perioden.</p>'}else{const requests=sickLeaveData.requests||[];$('#employeeSickRequests').innerHTML=requests.length?requests.map(r=>sickRequestHtml(r)).join(''):'<p class="muted">Du har ikke sendt noen fraværsmeldinger.</p>'}}
function updateSickForm(){const medical=$('#sickType').value==='medical_certificate',today=localDate();$('#sickStart').max=today;$('#sickEnd').max=today;$('#sickEndLabel').classList.toggle('hidden',!medical);$('#sickEnd').required=medical;if(!medical)$('#sickEnd').value=$('#sickStart').value;$('#submitSickLeave').disabled=!$('#sickRoutineAck').checked}
$('#openSickLeave').onclick=async()=>{const today=localDate();$('#sickStart').value=today;$('#sickStart').max=today;$('#sickEnd').value=today;$('#sickEnd').max=today;$('#sickRoutineAck').checked=false;updateSickForm();try{await loadSickLeave();$('#sickLeaveDialog').showModal()}catch(error){show(error.message)}};
$('#closeSickLeave').onclick=()=>$('#sickLeaveDialog').close();
$('#sickType').onchange=updateSickForm;$('#sickStart').onchange=updateSickForm;$('#sickRoutineAck').onchange=updateSickForm;
$('#sickLeaveForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter,type=$('#sickType').value,start=$('#sickStart').value,end=type==='medical_certificate'?$('#sickEnd').value:start;button.disabled=true;button.textContent='Sender …';try{const data=await authenticated('/functions/v1/sick-leave',{method:'POST',body:{action:'submit',absence_type:type,start_date:start,end_date:end,employee_note:$('#sickNote').value.trim(),routine_acknowledged:$('#sickRoutineAck').checked}});show(data.email_sent?'Sykefraværet er sendt til admin.':'Sykefraværet er registrert, men e-postvarselet kunne ikke sendes.');event.target.reset();await loadSickLeave();updateSickForm()}catch(error){show(error.message)}finally{button.textContent='Send sykefravær';updateSickForm()}};
const initialSickRange=monthRange();$('#sickStatsFrom').value=initialSickRange.from;$('#sickStatsTo').value=initialSickRange.to;
$('#loadSickStats').onclick=()=>loadSickLeave(true).catch(error=>show(error.message));
$('#adminSickRequests').onclick=async event=>{const button=event.target.closest('[data-sick-handle]');if(!button)return;const status=button.dataset.status,id=button.dataset.sickHandle,comment=document.querySelector(`[data-sick-comment="${id}"]`).value.trim();if(status==='rejected'&&comment.length<3)return show('Skriv en kort kommentar ved avvisning.');if(!confirm(status==='approved'?'Godkjenne fraværet og føre 8 timer per aktuell hverdag?':'Avvise fraværsmeldingen?'))return;button.disabled=true;try{await authenticated('/functions/v1/sick-leave',{method:'PATCH',body:{action:'handle',id,status,admin_comment:comment}});show(status==='approved'?'Fraværet er godkjent og ført i timelisten.':'Fraværet er avvist.');await loadSickLeave(true)}catch(error){show(error.message)}finally{button.disabled=false}};

const vacationTypeText=value=>({vacation:'Ferie',leave:'Permisjon'})[value]||value;
const vacationStatusText=value=>({pending:'Til behandling',approved:'Godkjent',rejected:'Avvist'})[value]||value;
const currentYear=()=>Number(localDate().slice(0,4));
function addLocalDays(value,days){const date=new Date(`${value}T12:00:00Z`);date.setUTCDate(date.getUTCDate()+days);return date.toISOString().slice(0,10)}
async function loadVacation(adminView=false){const year=adminView?Number($('#vacationAdminYear').value):currentYear();vacationData=await authenticated(`/functions/v1/vacation?year=${year}`);renderVacation(adminView)}
function vacationRequestHtml(r,adminView=false){const employee=r.employees||{},period=`${displayDate(r.start_date)}–${displayDate(r.end_date)}`;return `<article class="sick-request"><div class="sick-request-head"><div><strong>${adminView?`${escapeHtml(employee.employee_number||'')} · ${escapeHtml(employee.full_name||'')}`:vacationTypeText(r.request_type)}</strong><p>${adminView?vacationTypeText(r.request_type)+' · ':''}${period} · ${r.requested_days} ${r.requested_days===1?'dag':'dager'}</p>${r.employee_note?`<p class="muted">${escapeHtml(r.employee_note)}</p>`:''}${r.admin_comment?`<p class="muted">Kommentar: ${escapeHtml(r.admin_comment)}</p>`:''}</div><span class="status ${r.status}">${vacationStatusText(r.status)}</span></div>${adminView&&r.status==='pending'?vacationActions(r.id,'handle'):''}</article>`}
function carryoverHtml(r,adminView=false){const employee=r.employees||{};return `<article class="sick-request"><div class="sick-request-head"><div><strong>${adminView?`${escapeHtml(employee.employee_number||'')} · ${escapeHtml(employee.full_name||'')}`:'Overføring'}</strong><p>${r.days} ${r.days===1?'dag':'dager'} · ${r.from_year} → ${r.to_year}</p>${r.employee_note?`<p class="muted">${escapeHtml(r.employee_note)}</p>`:''}${r.admin_comment?`<p class="muted">Kommentar: ${escapeHtml(r.admin_comment)}</p>`:''}</div><span class="status ${r.status}">${vacationStatusText(r.status)}</span></div>${adminView&&r.status==='pending'?vacationActions(r.id,'handle_carryover'):''}</article>`}
function vacationActions(id,action){return `<div class="sick-actions"><label>Kommentar<textarea data-vacation-comment="${id}" rows="2" placeholder="Påkrevd ved avvisning"></textarea></label><button class="secondary" data-vacation-handle="${id}" data-action="${action}" data-status="rejected">Avvis</button><button class="primary" data-vacation-handle="${id}" data-action="${action}" data-status="approved">Godkjenn</button></div>`}
function renderVacation(adminView=false){if(adminView){const balances=vacationData.balances||[];$('#vacationBalances').innerHTML=balances.length?`<table><thead><tr><th>Ansatt</th><th>Tilgjengelig</th><th>Godkjent ferie</th><th>Til behandling</th><th>Overført ut</th><th>Gjenstår</th></tr></thead><tbody>${balances.map(b=>`<tr><td><strong>${escapeHtml(b.employee_number)} · ${escapeHtml(b.full_name)}</strong></td><td>${b.available}</td><td>${b.used}</td><td>${b.pending}</td><td>${b.transferred}</td><td><strong>${b.remaining}</strong></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Ingen ansatte funnet.</div>';$('#adminVacationRequests').innerHTML=(vacationData.requests||[]).length?vacationData.requests.map(r=>vacationRequestHtml(r,true)).join(''):'<p class="muted">Ingen søknader dette året.</p>';$('#adminCarryoverRequests').innerHTML=(vacationData.carryovers||[]).length?vacationData.carryovers.map(r=>carryoverHtml(r,true)).join(''):'<p class="muted">Ingen overføringssøknader dette året.</p>';return}const b=vacationData.balance||{};$('#vacationBalance').innerHTML=`<div><span>Tilgjengelig ${b.year||currentYear()}</span><strong>${b.available||25} dager</strong></div><div><span>Godkjent ferie</span><strong>${b.used||0} dager</strong></div><div><span>Gjenstår</span><strong>${b.remaining??25} dager</strong></div>`;$('#employeeVacationRequests').innerHTML=(vacationData.requests||[]).length?vacationData.requests.map(r=>vacationRequestHtml(r)).join(''):'<p class="muted">Du har ingen ferie- eller permisjonssøknader.</p>';$('#employeeCarryovers').innerHTML=(vacationData.carryovers||[]).length?vacationData.carryovers.map(r=>carryoverHtml(r)).join(''):'<p class="muted">Ingen overføringssøknader.</p>'}
function setVacationDates(){const earliest=addLocalDays(localDate(),14);$('#vacationStart').min=earliest;$('#vacationEnd').min=$('#vacationStart').value||earliest;if(!$('#vacationStart').value)$('#vacationStart').value=earliest;if(!$('#vacationEnd').value||$('#vacationEnd').value<$('#vacationStart').value)$('#vacationEnd').value=$('#vacationStart').value}
$('#openVacation').onclick=async()=>{setVacationDates();$('#carryoverYear').value=currentYear();try{await loadVacation();$('#vacationDialog').showModal()}catch(error){show(error.message)}};
$('#closeVacation').onclick=()=>$('#vacationDialog').close();$('#vacationStart').onchange=setVacationDates;
$('#vacationForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Sender …';try{const data=await authenticated('/functions/v1/vacation',{method:'POST',body:{action:'submit',request_type:$('#vacationType').value,start_date:$('#vacationStart').value,end_date:$('#vacationEnd').value,employee_note:$('#vacationNote').value.trim()}});show(data.email_sent?'Ønsket er sendt til admin.':'Ønsket er registrert, men e-postvarselet kunne ikke sendes.');event.target.reset();setVacationDates();await loadVacation()}catch(error){show(error.message)}finally{button.disabled=false;button.textContent='Send ønske'}};
$('#carryoverForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const data=await authenticated('/functions/v1/vacation',{method:'POST',body:{action:'carryover',from_year:Number($('#carryoverYear').value),days:Number($('#carryoverDays').value),employee_note:$('#carryoverNote').value.trim()}});show(data.email_sent?'Overføringssøknaden er sendt til admin.':'Søknaden er registrert, men e-postvarselet kunne ikke sendes.');event.target.reset();$('#carryoverYear').value=currentYear();await loadVacation()}catch(error){show(error.message)}finally{button.disabled=false}};
$('#vacationAdminYear').value=currentYear();$('#loadVacationAdmin').onclick=()=>loadVacation(true).catch(error=>show(error.message));
async function handleVacationClick(event){const button=event.target.closest('[data-vacation-handle]');if(!button)return;const id=button.dataset.vacationHandle,status=button.dataset.status,action=button.dataset.action,comment=document.querySelector(`[data-vacation-comment="${id}"]`).value.trim();if(status==='rejected'&&comment.length<3)return show('Skriv en kort kommentar ved avvisning.');if(!confirm(status==='approved'?'Godkjenne søknaden?':'Avvise søknaden?'))return;button.disabled=true;try{const data=await authenticated('/functions/v1/vacation',{method:'PATCH',body:{action,id,status,admin_comment:comment}});show(data.email_sent?(status==='approved'?'Søknaden er godkjent og den ansatte er varslet.':'Søknaden er avvist og den ansatte er varslet.'):'Søknaden er behandlet, men e-posten kunne ikke sendes.');await loadVacation(true)}catch(error){show(error.message)}finally{button.disabled=false}}
$('#adminVacationRequests').onclick=handleVacationClick;$('#adminCarryoverRequests').onclick=handleVacationClick;

const hrStatusText=value=>({draft:'Utkast',locked:'Låst – klar for signering',pending_signature:'Til signering',signed:'Signert',cancelled:'Avbrutt',not_required:'Ingen signering',pending:'Venter på signering',declined:'Avvist'})[value]||value;
const defaultContractModules=()=>[
['Ansettelse og tiltredelse','Arbeidstaker ansettes i en fast stilling som [stilling] med tiltredelse fra [dato].\n\nStillingsandel: [prosent] %.'],
['Prøvetid','Prøvetiden er på [antall] måneder fra tiltredelsesdato. I prøvetiden gjelder en gjensidig oppsigelsesfrist på 14 dager. Eventuell forlengelse ved fravær håndteres etter gjeldende regler.'],
['Arbeidsoppgaver','Arbeidstaker skal utføre oppgaver som hører til stillingen. Arbeidsgiver kan utarbeide stillingsinstruks og gjøre saklige endringer innenfor lovverket og eventuell tariffavtale.\n\nArbeidstaker rapporterer til [leder/stilling].'],
['Arbeidssted','Arbeidssted er for tiden [arbeidssted]. Arbeidsstedet kan endres ved saklig behov. Arbeidstaker må påregne reising i den grad stillingen krever det.'],
['Arbeidstid og pause','Normal arbeidstid er [tidspunkt], [ukedager], med [pause]. Ukentlig normalarbeidstid er [timer] timer. Arbeid utover avtalt tid skal være pålagt eller godkjent og håndteres etter gjeldende regler.'],
['Lønn og andre godtgjørelser','Avtalt lønn er kr [beløp] per [time/måned]. Lønn utbetales den [dato] hver måned til oppgitt bankkonto. Overtid skal avtales på forhånd og kompenseres etter gjeldende regler og eventuell tariffavtale.'],
['Pensjons- og forsikringsordninger','Arbeidstaker omfattes av arbeidsgivers til enhver tid gjeldende pensjons- og forsikringsordninger.\n\nPensjon: [ordning]\nForsikring: [ordning]'],
['Ferie og feriegodtgjørelse','Rett til ferie og feriepenger og fastsettelse av ferietidspunkt følger ferieloven og virksomhetens gjeldende ordninger. Feriepengesats: [prosent] %.'],
['Oppsigelse','Gjensidig oppsigelsesfrist er [antall] måned(er), med mindre lengre frist følger av gjeldende regler. Oppsigelse skal være skriftlig. Ved fratredelse skal arbeidstaker returnere arbeidsgivers eiendeler og materiale.'],
['Arbeidstakers plikter ved sykefravær','Arbeidstaker skal følge virksomhetens sykefraværsrutiner og varsle nærmeste leder så snart som mulig. Fravær dokumenteres etter gjeldende regler.'],
['Tidsregistrering','Arbeidstaker skal bruke Apart Tid for registrering av arbeidstid og følge virksomhetens rutiner for inn- og utstempling.']
].map(([title,body])=>({id:crypto.randomUUID(),title,body,active:true}));
async function loadHr(){hrData=await authenticated('/functions/v1/hr');renderHr()}
function hrDocumentRows(adminView=false){const docs=hrData.documents||[];return docs.length?docs.map(d=>`<div class="hms-row"><div><strong>${escapeHtml(d.title)}</strong><small>${adminView?`${escapeHtml(d.employees?.employee_number||'')} · ${escapeHtml(d.employees?.full_name||'')} · `:''}${new Date(d.created_at).toLocaleDateString('nb-NO')} · ${hrStatusText(d.signature_status)}${d.read_at?' · Lest':''}</small></div><div class="actions"><a class="small hms-link" href="${d.url}" target="_blank" rel="noopener" data-hr-open="${d.id}">Åpne PDF</a></div></div>`).join(''):'<p class="muted">Ingen dokumenter er lagt inn.</p>'}
function contractPreview(c){const modules=c.locked_modules||c.modules||[];return modules.filter(m=>m.active).map((m,i)=>`<section><strong>${i+1} ${escapeHtml(m.title)}</strong><p>${escapeHtml(m.body).replaceAll('\n','<br>')}</p></section>`).join('')}
function hrContractRows(adminView=false){const contracts=hrData.contracts||[];return contracts.length?contracts.map(c=>`<article class="sick-request"><div class="sick-request-head"><div><strong>${escapeHtml(c.title)}</strong><p>${adminView?`${escapeHtml(c.employees?.employee_number||'')} · ${escapeHtml(c.employees?.full_name||'')} · `:''}Versjon ${c.version}</p></div><span class="status ${c.status}">${hrStatusText(c.status)}</span></div><details><summary>Vis kontrakt</summary><div class="contract-preview">${contractPreview(c)}</div></details><div class="actions">${adminView&&c.status==='draft'?`<button class="secondary" data-contract-edit="${c.id}">Rediger</button><button class="primary" data-contract-lock="${c.id}">Lås kontrakt</button>`:''}${c.status!=='draft'? `<button class="secondary" data-contract-pdf="${c.id}">Last ned PDF</button>`:''}</div></article>`).join(''):'<p class="muted">Ingen kontrakter er opprettet.</p>'}
function renderHr(){if(currentEmployee?.role==='admin'){const options='<option value="">Velg ansatt</option>'+hrData.employees.map(e=>`<option value="${e.id}">${escapeHtml(e.employee_number)} · ${escapeHtml(e.full_name)}</option>`).join('');$('#hrDocumentEmployee').innerHTML='<option value="all">Alle ansatte</option>'+options.slice(options.indexOf('</option>')+9);$('#hrContractEmployee').innerHTML=options;$('#adminHrDocuments').innerHTML=hrDocumentRows(true);$('#adminHrContracts').innerHTML=hrContractRows(true)}else{$('#employeeHrDocuments').innerHTML=hrDocumentRows(false);$('#employeeHrContracts').innerHTML=hrContractRows(false)}}
$('#openEmployeeHr').onclick=async()=>{try{await loadHr();$('#employeeHrDialog').showModal()}catch(error){show(error.message)}};
$('#closeEmployeeHr').onclick=()=>$('#employeeHrDialog').close();
$('#employeeHrDocuments').onclick=async event=>{const link=event.target.closest('[data-hr-open]');if(link)authenticated('/functions/v1/hr',{method:'PATCH',body:{action:'mark_read',id:link.dataset.hrOpen}}).catch(()=>{})};
$('#hrUploadForm').onsubmit=async event=>{event.preventDefault();const file=$('#hrDocumentFile').files[0],button=event.submitter;if(!file)return;button.disabled=true;button.textContent='Laster opp …';try{const data=await authenticated('/functions/v1/hr',{method:'POST',body:{action:'upload_document',title:$('#hrDocumentTitle').value.trim(),employee_id:$('#hrDocumentEmployee').value,file_name:file.name,mime_type:file.type||'application/pdf',content_base64:await fileBase64(file),requires_signature:$('#hrRequiresSignature').checked}});event.target.reset();show(`Dokumentet er lagt i arkivet til ${data.recipient_count} mottaker(e).`);await loadHr()}catch(error){show(error.message)}finally{button.disabled=false;button.textContent='Last opp og varsle'}};
function renderContractModules(){$('#hrContractModules').innerHTML=contractModules.map((m,i)=>`<article class="contract-module ${m.active?'':'inactive'}" data-module-index="${i}"><div class="module-head"><label class="check-row"><input type="checkbox" data-module-active ${m.active?'checked':''}> Aktiv</label><div class="actions"><button type="button" class="small" data-module-up ${i===0?'disabled':''}>Opp</button><button type="button" class="small" data-module-down ${i===contractModules.length-1?'disabled':''}>Ned</button><button type="button" class="danger" data-module-delete>Fjern</button></div></div><label>Overskrift<input data-module-title value="${escapeHtml(m.title)}" required></label><label>Innhold<textarea data-module-body rows="6" required>${escapeHtml(m.body)}</textarea></label></article>`).join('')}
function resetContractForm(){$('#hrContractForm').reset();$('#hrContractId').value='';$('#hrContractTitle').value='Arbeidsavtale';$('#hrContractEmployee').disabled=false;$('#cancelContractEdit').classList.add('hidden');contractModules=defaultContractModules();renderContractModules()}
$('#addContractModule').onclick=()=>{contractModules.push({id:crypto.randomUUID(),title:'Nytt punkt',body:'Skriv inn innhold.',active:true});renderContractModules()};
$('#hrContractModules').oninput=event=>{const row=event.target.closest('[data-module-index]');if(!row)return;const m=contractModules[Number(row.dataset.moduleIndex)];if(event.target.matches('[data-module-title]'))m.title=event.target.value;if(event.target.matches('[data-module-body]'))m.body=event.target.value;if(event.target.matches('[data-module-active]')){m.active=event.target.checked;row.classList.toggle('inactive',!m.active)}};
$('#hrContractModules').onclick=event=>{const row=event.target.closest('[data-module-index]');if(!row)return;const i=Number(row.dataset.moduleIndex);if(event.target.closest('[data-module-up]')&&i>0)[contractModules[i-1],contractModules[i]]=[contractModules[i],contractModules[i-1]];else if(event.target.closest('[data-module-down]')&&i<contractModules.length-1)[contractModules[i+1],contractModules[i]]=[contractModules[i],contractModules[i+1]];else if(event.target.closest('[data-module-delete]'))contractModules.splice(i,1);else return;renderContractModules()};
$('#hrContractForm').onsubmit=async event=>{event.preventDefault();const id=$('#hrContractId').value,button=event.submitter;if(!contractModules.some(m=>m.active))return show('Behold minst én aktiv kontraktsmodul.');button.disabled=true;try{await authenticated('/functions/v1/hr',{method:id?'PATCH':'POST',body:{action:id?'update_contract':'create_contract',...(id?{id}:{}),employee_id:$('#hrContractEmployee').value,title:$('#hrContractTitle').value.trim(),modules:contractModules}});show(id?'Kontraktsutkastet er oppdatert.':'Kontraktsutkastet er opprettet.');resetContractForm();await loadHr()}catch(error){show(error.message)}finally{button.disabled=false}};
$('#cancelContractEdit').onclick=resetContractForm;
async function downloadContractPdf(id){const data=await authenticated('/functions/v1/hr',{method:'POST',body:{action:'download_contract_pdf',id}}),bytes=Uint8Array.from(atob(data.content_base64),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),link=document.createElement('a');link.href=url;link.download=data.file_name;link.click();URL.revokeObjectURL(url)}
async function handleContractListClick(event){const edit=event.target.closest('[data-contract-edit]'),lock=event.target.closest('[data-contract-lock]'),pdf=event.target.closest('[data-contract-pdf]');if(edit){const c=hrData.contracts.find(x=>x.id===edit.dataset.contractEdit);$('#hrContractId').value=c.id;$('#hrContractEmployee').value=c.employee_id;$('#hrContractEmployee').disabled=true;$('#hrContractTitle').value=c.title;contractModules=structuredClone(c.modules||[]);$('#cancelContractEdit').classList.remove('hidden');renderContractModules();$('#hrContractTitle').focus()}if(lock){if(!confirm('Låse kontrakten? Innholdet kan ikke redigeres etterpå.'))return;lock.disabled=true;try{const data=await authenticated('/functions/v1/hr',{method:'PATCH',body:{action:'lock_contract',id:lock.dataset.contractLock}});show(data.email_sent?'Kontrakten er låst og den ansatte er varslet.':'Kontrakten er låst, men e-postvarselet kunne ikke sendes.');await loadHr()}catch(error){show(error.message)}finally{lock.disabled=false}}if(pdf){pdf.disabled=true;try{await downloadContractPdf(pdf.dataset.contractPdf)}catch(error){show(error.message)}finally{pdf.disabled=false}}}
$('#adminHrContracts').onclick=handleContractListClick;$('#employeeHrContracts').onclick=handleContractListClick;
resetContractForm();

async function loadDashboard(){if(!dashboardDate)dashboardDate=localDate();dashboardData=await authenticated(`/functions/v1/admin-dashboard?date=${dashboardDate}`);renderDashboard()}
function dashboardDateText(value){return new Date(`${value}T12:00:00`).toLocaleDateString('nb-NO',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}
function dashboardAddDays(value,days){const date=new Date(`${value}T12:00:00`);date.setDate(date.getDate()+days);return date.toISOString().slice(0,10)}
function dashboardInitials(value){return String(value||'').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function renderDashboard(){const data=dashboardData,summary=data.summary;$('#dashboardDateLabel').textContent=dashboardDateText(data.date);$('#dashboardStats').innerHTML=`<article class="card dashboard-stat"><span>På jobb i dag</span><strong>${summary.expected} av ${summary.active_staff}</strong></article><article class="card dashboard-stat"><span>Stemplet inn nå</span><strong>${summary.clocked_in}</strong></article><article class="card dashboard-stat attention"><span>Krever behandling</span><strong>${summary.tasks}</strong></article><article class="card dashboard-stat"><span>Planlagte timer</span><strong>${summary.planned_hours==null?'–':hours(summary.planned_hours)}</strong></article>`;$('#dashboardRosterSource').textContent=data.roster_active?'Publisert vaktliste + fravær':'Aktive ansatte minus registrert fravær';$('#dashboardFallback').classList.toggle('hidden',data.roster_active);$('#dashboardFallback').textContent='Ingen publisert vaktliste denne dagen. Bemanningen viser aktive ansatte minus godkjent ferie, permisjon og registrert sykefravær.';$('#dashboardPeople').innerHTML=data.people.length?data.people.map(person=>`<article class="dashboard-person"><span class="avatar">${dashboardInitials(person.full_name)}</span><div><strong>${escapeHtml(person.full_name)}</strong><small>${escapeHtml(person.detail)}</small></div><span class="dashboard-person-state ${person.status==='away'?'away':''}">${escapeHtml(person.status_label)}</span></article>`).join(''):'<div class="empty">Ingen ansatte er forventet denne dagen.</div>';$('#dashboardTaskBadge').textContent=`${summary.tasks} åpne`;$('#dashboardTasks').innerHTML=data.tasks.map(task=>`<article class="dashboard-task ${task.count?'':'done'}"><span class="dashboard-task-icon">${({vacation:'F',hms:'H',contract:'K',clock:'T'})[task.type]||'•'}</span><div><strong>${escapeHtml(task.label)}</strong><small>${escapeHtml(task.detail)}</small></div><button class="small" data-dashboard-target="${task.target}">${task.count?'Åpne':'Se'}</button></article>`).join('');$('#dashboardActivity').innerHTML=data.activity.length?data.activity.map(item=>`<article class="dashboard-event"><span></span><strong>${escapeHtml(item.text)}</strong><time>${new Date(item.at).toLocaleTimeString('nb-NO',{timeZone:'Europe/Oslo',hour:'2-digit',minute:'2-digit'})}</time></article>`).join(''):'<div class="empty">Ingen aktivitet denne dagen.</div>'}
function moveDashboardDate(days){dashboardDate=dashboardAddDays(dashboardDate,days);loadDashboard().catch(error=>show(error.message))}$('#dashboardPrevious').onclick=()=>moveDashboardDate(-1);$('#dashboardNext').onclick=()=>moveDashboardDate(1);$('#dashboardToday').onclick=()=>{dashboardDate=localDate();loadDashboard().catch(error=>show(error.message))};$('#dashboardTasks').onclick=event=>{const button=event.target.closest('[data-dashboard-target]');if(button)activateAdminPanel(button.dataset.dashboardTarget)};

async function loadCourses(){courseData=await authenticated('/functions/v1/courses');currentEmployee?.role==='admin'?renderAdminCourses():renderEmployeeCourses()}
function courseStatusText(status){return({draft:'Utkast',locked:'Låst',archived:'Arkivert',assigned:'Ikke startet',in_progress:'Påbegynt',completed:'Fullført'})[status]||status}
function courseDate(value){return value?new Date(value).toLocaleDateString('nb-NO',{day:'2-digit',month:'2-digit',year:'numeric'}):'–'}
function renderAdminCourses(){const order={locked:0,draft:1,archived:2},items=[...(courseData.courses||[])].sort((a,b)=>(order[a.status]??9)-(order[b.status]??9)||new Date(b.updated_at)-new Date(a.updated_at));$('#adminCourses').innerHTML=items.length?items.map(c=>{const assigned=(courseData.assignments||[]).filter(a=>a.course_id===c.id),completed=assigned.filter(a=>a.status==='completed').length,recipientOptions='<option value="all">Alle aktive ansatte</option>'+courseData.employees.map(e=>`<option value="${e.id}">${escapeHtml(e.employee_number)} · ${escapeHtml(e.full_name)}</option>`).join('');return `<article class="card course-admin-card"><div class="course-card-head"><div><span class="status ${c.status}">${courseStatusText(c.status)}</span><h3>${escapeHtml(c.title)}</h3><p class="muted">Versjon ${c.version} · ${c.modules.filter(m=>m.active).length} kapitler · ${c.questions.filter(q=>q.active).length} spørsmål</p></div><div class="actions">${c.status==='draft'?`<button class="secondary" data-course-edit="${c.id}">Rediger</button><button class="primary" data-course-lock="${c.id}">Lås kurs</button>`:`<button class="secondary" data-course-version="${c.id}">Lag ny versjon</button>`}</div></div><p>${escapeHtml(c.description||'Ingen beskrivelse.')}</p>${c.status==='locked'?`<div class="course-assign"><label>Send til<select data-course-recipient="${c.id}">${recipientOptions}</select></label><button class="primary" data-course-assign="${c.id}">Send kurs</button></div><p class="hint">Tildelt ${assigned.length} · fullført ${completed}</p>${assigned.length?`<details><summary>Vis deltakerlogg</summary><div class="course-log">${assigned.map(a=>`<div><span>${escapeHtml(a.employees?.full_name||'Ukjent')}</span><span>${courseStatusText(a.status)}${a.score!=null?` · ${a.score} %`:''}</span></div>`).join('')}</div></details>`:''}`:''}</article>`}).join(''):'<div class="card empty">Ingen kurs er opprettet ennå.</div>'}
function blankCourseModule(){return{id:crypto.randomUUID(),title:'Nytt kapittel',body:'',active:true}}
function blankCourseQuestion(){return{id:crypto.randomUUID(),text:'',options:['','',''],correct_index:0,active:true}}
function renderCourseEditor(){$('#courseModules').innerHTML=courseModules.map((m,i)=>`<article class="contract-module ${m.active?'':'inactive'}" data-course-module="${i}"><div class="module-head"><label class="check-row"><input type="checkbox" data-course-module-active ${m.active?'checked':''}> Aktiv</label><div class="actions"><button type="button" class="small" data-course-module-up ${i===0?'disabled':''}>Opp</button><button type="button" class="small" data-course-module-down ${i===courseModules.length-1?'disabled':''}>Ned</button><button type="button" class="danger" data-course-module-delete>Fjern</button></div></div><label>Overskrift<input data-course-module-title value="${escapeHtml(m.title)}" required></label><label>Tekst<textarea data-course-module-body rows="7" required>${escapeHtml(m.body)}</textarea></label></article>`).join('');$('#courseQuestions').innerHTML=courseQuestions.map((q,i)=>`<article class="contract-module ${q.active?'':'inactive'}" data-course-question="${i}"><div class="module-head"><label class="check-row"><input type="checkbox" data-course-question-active ${q.active?'checked':''}> Aktiv</label><button type="button" class="danger" data-course-question-delete>Fjern</button></div><label>Spørsmål<input data-course-question-text value="${escapeHtml(q.text)}" required></label><div class="course-options">${q.options.map((option,j)=>`<label class="course-option-edit"><input type="radio" name="correct-${i}" data-course-correct="${j}" ${q.correct_index===j?'checked':''}><span>Riktig svar</span><input data-course-option="${j}" value="${escapeHtml(option)}" placeholder="Svaralternativ ${j+1}" required></label>`).join('')}</div></article>`).join('')}
function resetCourseEditor(course=null){$('#courseEditorForm').reset();$('#courseId').value=course?.id||'';$('#courseTitle').value=course?.title||'';$('#courseDescription').value=course?.description||'';$('#coursePassingScore').value=course?.passing_score||80;$('#courseEditorHeading').textContent=course?`Rediger ${course.title}`:'Nytt kurs';courseModules=structuredClone(course?.modules||[blankCourseModule()]);courseQuestions=structuredClone(course?.questions||[blankCourseQuestion()]);renderCourseEditor()}
$('#newCourse').onclick=()=>{resetCourseEditor();$('#courseEditorDialog').showModal()};$('#cancelCourseEdit').onclick=()=>$('#courseEditorDialog').close();$('#addCourseModule').onclick=()=>{courseModules.push(blankCourseModule());renderCourseEditor()};$('#addCourseQuestion').onclick=()=>{courseQuestions.push(blankCourseQuestion());renderCourseEditor()};
$('#courseModules').oninput=event=>{const row=event.target.closest('[data-course-module]');if(!row)return;const m=courseModules[Number(row.dataset.courseModule)];if(event.target.matches('[data-course-module-title]'))m.title=event.target.value;if(event.target.matches('[data-course-module-body]'))m.body=event.target.value;if(event.target.matches('[data-course-module-active]'))m.active=event.target.checked};
$('#courseModules').onclick=event=>{const row=event.target.closest('[data-course-module]');if(!row)return;const i=Number(row.dataset.courseModule);if(event.target.closest('[data-course-module-up]')&&i>0)[courseModules[i-1],courseModules[i]]=[courseModules[i],courseModules[i-1]];else if(event.target.closest('[data-course-module-down]')&&i<courseModules.length-1)[courseModules[i+1],courseModules[i]]=[courseModules[i],courseModules[i+1]];else if(event.target.closest('[data-course-module-delete]'))courseModules.splice(i,1);else return;renderCourseEditor()};
$('#courseQuestions').oninput=event=>{const row=event.target.closest('[data-course-question]');if(!row)return;const q=courseQuestions[Number(row.dataset.courseQuestion)];if(event.target.matches('[data-course-question-text]'))q.text=event.target.value;if(event.target.matches('[data-course-option]'))q.options[Number(event.target.dataset.courseOption)]=event.target.value;if(event.target.matches('[data-course-correct]'))q.correct_index=Number(event.target.dataset.courseCorrect);if(event.target.matches('[data-course-question-active]'))q.active=event.target.checked};
$('#courseQuestions').onclick=event=>{const row=event.target.closest('[data-course-question]');if(row&&event.target.closest('[data-course-question-delete]')){courseQuestions.splice(Number(row.dataset.courseQuestion),1);renderCourseEditor()}};
$('#courseEditorForm').onsubmit=async event=>{event.preventDefault();const id=$('#courseId').value,button=event.submitter;if(!courseModules.some(m=>m.active&&m.title.trim()&&m.body.trim()))return show('Legg til minst ett aktivt kapittel med tekst.');if(!courseQuestions.some(q=>q.active&&q.text.trim()&&q.options.length>=2&&q.options.every(x=>x.trim())))return show('Legg til minst ett aktivt spørsmål med utfylte svaralternativer.');button.disabled=true;try{await authenticated('/functions/v1/courses',{method:id?'PATCH':'POST',body:{action:id?'update':'create',...(id?{id}:{}),title:$('#courseTitle').value.trim(),description:$('#courseDescription').value.trim(),passing_score:Number($('#coursePassingScore').value),modules:courseModules,questions:courseQuestions}});$('#courseEditorDialog').close();show(id?'Kursutkastet er oppdatert.':'Kursutkastet er opprettet.');await loadCourses()}catch(error){show(error.message)}finally{button.disabled=false}};
$('#adminCourses').onclick=async event=>{const edit=event.target.closest('[data-course-edit]'),lock=event.target.closest('[data-course-lock]'),version=event.target.closest('[data-course-version]'),assign=event.target.closest('[data-course-assign]');if(edit){const course=courseData.courses.find(c=>c.id===edit.dataset.courseEdit);resetCourseEditor(course);$('#courseEditorDialog').showModal()}if(lock){if(!confirm('Låse kurset? Denne versjonen kan ikke redigeres etterpå.'))return;lock.disabled=true;try{await authenticated('/functions/v1/courses',{method:'PATCH',body:{action:'lock',id:lock.dataset.courseLock}});show('Kurset er låst og klart til utsending.');await loadCourses()}catch(error){show(error.message)}finally{lock.disabled=false}}if(version){version.disabled=true;try{await authenticated('/functions/v1/courses',{method:'POST',body:{action:'new_version',id:version.dataset.courseVersion}});show('En ny kursversjon er opprettet som utkast.');await loadCourses()}catch(error){show(error.message)}finally{version.disabled=false}}if(assign){const select=document.querySelector(`[data-course-recipient="${assign.dataset.courseAssign}"]`);if(!confirm(`Sende kurset til ${select.options[select.selectedIndex].text}?`))return;assign.disabled=true;try{const data=await authenticated('/functions/v1/courses',{method:'POST',body:{action:'assign',course_id:assign.dataset.courseAssign,employee_id:select.value}});show(data.assigned_count?`Kurset er sendt til ${data.assigned_count} ansatt(e).`:'Kurset var allerede sendt til valgte ansatte.');await loadCourses()}catch(error){show(error.message)}finally{assign.disabled=false}}};
function renderEmployeeCourses(){const items=courseData.assignments||[];$('#employeeCourses').innerHTML=items.length?['assigned','in_progress','completed'].map(status=>{const rows=items.filter(a=>a.status===status);return rows.length?`<section class="course-group"><h3>${courseStatusText(status)}</h3>${rows.map(a=>`<button class="course-employee-card" data-course-open="${a.id}"><span><strong>${escapeHtml(a.courses.title)}</strong><small>Versjon ${a.courses.version} · tildelt ${courseDate(a.assigned_at)}</small></span><span>${a.status==='completed'?`${a.score} %`:'Åpne'}</span></button>`).join('')}</section>`:''}).join(''):'<div class="empty">Du har ingen tildelte kurs.</div>'}
async function openCourseReader(id){activeCourseAssignment=(courseData.assignments||[]).find(a=>a.id===id);if(!activeCourseAssignment)return;const a=activeCourseAssignment,c=a.courses;$('#courseReaderVersion').textContent=`Versjon ${c.version} · ${courseStatusText(a.status)}`;$('#courseReaderTitle').textContent=c.title;$('#courseReaderDescription').textContent=c.description||'';$('#courseReaderModules').innerHTML=(c.modules||[]).filter(m=>m.active).map((m,i)=>`<section class="course-chapter"><span>${i+1}</span><div><h3>${escapeHtml(m.title)}</h3>${escapeHtml(m.body).replace(/\n/g,'<br>')}</div></section>`).join('');$('#courseReaderQuestions').innerHTML=(c.questions||[]).map((q,i)=>`<fieldset><legend>${i+1}. ${escapeHtml(q.text)}</legend>${q.options.map((option,j)=>`<label class="test-option"><input type="radio" name="question-${escapeHtml(q.id)}" value="${j}" required><span>${escapeHtml(option)}</span></label>`).join('')}</fieldset>`).join('');const submit=$('#courseTestForm button.primary');submit.classList.toggle('hidden',a.status==='completed');$('#courseTestForm>p').textContent=a.status==='completed'?`Fullført ${courseDate(a.completed_at)} med ${a.score} %.`:'Alle spørsmål må besvares. Du kan prøve på nytt dersom testen ikke bestås.';$('#courseReaderDialog').showModal();if(a.status==='assigned'){await authenticated('/functions/v1/courses',{method:'PATCH',body:{action:'start',assignment_id:a.id}});a.status='in_progress';renderEmployeeCourses()}}
$('#openCourses').onclick=async()=>{try{await loadCourses();$('#coursesDialog').showModal()}catch(error){show(error.message)}};$('#closeCourses').onclick=()=>$('#coursesDialog').close();$('#closeCourseReader').onclick=()=>$('#courseReaderDialog').close();$('#employeeCourses').onclick=event=>{const open=event.target.closest('[data-course-open]');if(open)openCourseReader(open.dataset.courseOpen).catch(error=>show(error.message))};
$('#courseTestForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter,questions=activeCourseAssignment.courses.questions||[],answers=questions.map(q=>({question_id:q.id,option_index:Number(new FormData(event.target).get(`question-${q.id}`))}));button.disabled=true;button.textContent='Kontrollerer …';try{const data=await authenticated('/functions/v1/courses',{method:'POST',body:{action:'submit',assignment_id:activeCourseAssignment.id,answers}});show(data.passed?`Bestått med ${data.score} %. Kurset er fullført.`:`Du fikk ${data.score} %. Du må ha ${data.passing_score} % for å bestå.`);await loadCourses();$('#courseReaderDialog').close()}catch(error){show(error.message)}finally{button.disabled=false;button.textContent='Lever svar'}};

const rosterTypes={day:'Dagskift',evening:'Kveldsskift',night:'Nattskift'};
const rosterNightPresets={night1:{label:'Nattskift 1',start:'23:00',end:'07:00'},night2:{label:'Nattskift 2',start:'00:00',end:'06:00'}};
function rosterIso(date){return date.toISOString().slice(0,10)}
function rosterMonday(value=new Date()){const d=value instanceof Date?new Date(value):new Date(`${value}T12:00:00`),day=d.getDay()||7;d.setDate(d.getDate()-day+1);return rosterIso(d)}
function rosterAddDays(value,days){const d=new Date(`${value}T12:00:00`);d.setDate(d.getDate()+days);return rosterIso(d)}
function rosterDayLabel(value){return new Date(`${value}T12:00:00`).toLocaleDateString('nb-NO',{weekday:'long',day:'numeric',month:'short'})}
function rosterDayParts(value){const date=new Date(`${value}T12:00:00`);return{weekday:date.toLocaleDateString('nb-NO',{weekday:'long'}),date:date.toLocaleDateString('nb-NO',{day:'numeric',month:'short'})}}
function rosterWeekLabel(value){const end=rosterAddDays(value,6),weekNumber=(()=>{const d=new Date(`${value}T12:00:00Z`),start=new Date(Date.UTC(d.getUTCFullYear(),0,4)),startDay=start.getUTCDay()||7,startMonday=new Date(start);startMonday.setUTCDate(start.getUTCDate()-startDay+1);return Math.floor((d-startMonday)/604800000)+1})();return `Uke ${weekNumber} · ${new Date(`${value}T12:00:00`).toLocaleDateString('nb-NO',{day:'numeric',month:'short'})}–${new Date(`${end}T12:00:00`).toLocaleDateString('nb-NO',{day:'numeric',month:'short',year:'numeric'})}`}
function rosterTime(value){return String(value||'').slice(0,5).replace(':','.')}
function rosterMinutes(value){const[a,b]=String(value).slice(0,5).split(':').map(Number);return a*60+b}
function rosterCrossesMidnight(shift){return rosterMinutes(shift.end_time)<=rosterMinutes(shift.start_time)}
function rosterDuration(shift){let value=rosterMinutes(shift.end_time)-rosterMinutes(shift.start_time);if(value<=0)value+=1440;return value/60}
function rosterNightSlot(shift){return rosterMinutes(shift.start_time)>=12*60?'night1':'night2'}
function rosterShiftLabel(shift){return shift.shift_type==='night'?rosterNightPresets[rosterNightSlot(shift)].label:rosterTypes[shift.shift_type]}
function rosterMoney(value){return Number(value||0).toLocaleString('nb-NO',{style:'currency',currency:'NOK',minimumFractionDigits:0,maximumFractionDigits:0})}
function rosterWeeklyCapacity(employee){const percent=Number(employee.position_percent);return Number.isFinite(percent)&&percent>0?165*12/52*percent/100:null}
function rosterSettings(){const s=rosterData.settings||{};return{day:[s.day_start||'08:00',s.day_end||'16:00'],evening:[s.evening_start||'16:00',s.evening_end||'23:00'],night:[s.night_start||'23:00',s.night_end||'07:00']}}
async function loadRoster(employeeView=false){const week=employeeView?employeeRosterWeekStart:rosterWeekStart;rosterData=await authenticated(`/functions/v1/roster?week=${week}`);if(!employeeView){const insights=await authenticated('/functions/v1/roster-insights');const detailMap=new Map((insights.employees||[]).map(x=>[x.employee_id,x]));rosterData.employees=(rosterData.employees||[]).map(employee=>({...employee,...(detailMap.get(employee.id)||{position_percent:null,salary_type:null,salary_rate:null})}))}employeeView?renderEmployeeRoster():renderAdminRoster()}
function renderAdminRoster(){
  const schedule=rosterData.schedule,status=schedule?.status||'draft',dirty=Boolean(schedule?.published_at&&new Date(schedule.updated_at)>new Date(schedule.published_at));
  $('#rosterWeekLabel').textContent=rosterWeekLabel(rosterWeekStart);
  $('#rosterStatus').textContent=({draft:'Utkast',published:'Publisert',inactive:'Inaktiv'})[status];
  $('#rosterChangeStatus').textContent=dirty&&status==='published'?'Endringer er ikke publisert ennå.':'';
  $('#deactivateRoster').classList.toggle('hidden',status!=='published');
  $('#publishRoster').textContent=status==='published'?(dirty?'Publiser endringer':'Publiser på nytt'):'Publiser vaktliste';

  const days=Array.from({length:7},(_,i)=>rosterAddDays(rosterWeekStart,i));
  const allShifts=rosterData.shifts||[],allAbsences=rosterData.absences||[];
  const shiftsByDay=new Map(days.map(date=>[date,allShifts.filter(x=>x.work_date===date)]));
  const absencesByDay=new Map(days.map(date=>[date,allAbsences.filter(x=>x.start_date<=date&&x.end_date>=date)]));
  const rows=Object.fromEntries(['day','evening'].map(type=>[type,Math.max(2,...days.map(date=>shiftsByDay.get(date).filter(x=>x.shift_type===type).length))]));
  const nightRows=Object.fromEntries(Object.keys(rosterNightPresets).map(slot=>[slot,Math.max(1,...days.map(date=>shiftsByDay.get(date).filter(x=>x.shift_type==='night'&&rosterNightSlot(x)===slot).length))]));
  const absenceRows=Math.max(0,...days.map(date=>absencesByDay.get(date).length));
  const week=$('#rosterWeek');
  week.style.setProperty('--day-shift-height',`${rows.day*144-8}px`);
  week.style.setProperty('--evening-shift-height',`${rows.evening*144-8}px`);
  week.style.setProperty('--night-one-height',`${nightRows.night1*144-8}px`);
  week.style.setProperty('--night-two-height',`${nightRows.night2*144-8}px`);
  week.style.setProperty('--absence-height',`${absenceRows*80}px`);

  const shiftCard=shift=>{const employee=rosterData.employees.find(e=>e.id===shift.employee_id);return `<article class="roster-shift ${shift.shift_type}" data-roster-shift="${shift.id}"><strong>${escapeHtml(employee?.full_name||'Ansatt')}</strong><span>${rosterShiftLabel(shift)} · ${rosterTime(shift.start_time)}–${rosterTime(shift.end_time)}${rosterCrossesMidnight(shift)?' · neste dag':''}</span><div><button class="small" data-roster-edit="${shift.id}">Rediger</button><button class="small roster-delete" data-roster-delete="${shift.id}">Fjern</button></div></article>`};
  week.innerHTML=days.map(date=>{
    const shifts=shiftsByDay.get(date),absences=absencesByDay.get(date);
    const dayParts=rosterDayParts(date);
    const absenceGroup=absenceRows?`<div class="roster-absence-group">${absences.map(a=>{const employee=rosterData.employees.find(e=>e.id===a.employee_id);return `<div class="roster-absence"><strong>${escapeHtml(employee?.full_name||'Ansatt')}</strong><span>${a.request_type==='vacation'?'Ferie':'Permisjon'}</span></div>`}).join('')}</div>`:'';
    const standardGroups=['day','evening'].map(type=>{const items=shifts.filter(x=>x.shift_type===type),empty=Array.from({length:rows[type]-items.length},()=>`<div class="roster-empty-slot"><button type="button" class="roster-quick-add" data-roster-quick-date="${date}" data-roster-quick-type="${type}" aria-label="Legg til ${rosterTypes[type].toLowerCase()} ${rosterDayLabel(date)}">+</button></div>`).join('');return `<div class="roster-shift-group ${type}-group" aria-label="${rosterTypes[type]}">${items.map(shiftCard).join('')}${empty}</div>`}).join('');
    const nightGroup=`<div class="roster-shift-group night-group" aria-label="Nattskift">${Object.entries(rosterNightPresets).map(([slot,preset])=>{const items=shifts.filter(x=>x.shift_type==='night'&&rosterNightSlot(x)===slot),empty=Array.from({length:nightRows[slot]-items.length},()=>`<div class="roster-empty-slot night-slot-empty"><span>${preset.label}<small>${rosterTime(preset.start)}–${rosterTime(preset.end)}</small></span><button type="button" class="roster-quick-add" data-roster-quick-date="${date}" data-roster-quick-type="night" data-roster-quick-start="${preset.start}" data-roster-quick-end="${preset.end}" data-roster-quick-label="${preset.label}" aria-label="Legg til ${preset.label.toLowerCase()} ${rosterDayLabel(date)}">+</button></div>`).join('');return `<div class="roster-night-slot ${slot}">${items.map(shiftCard).join('')}${empty}</div>`}).join('')}</div>`;
    const shiftGroups=standardGroups+nightGroup;
    return `<section class="roster-day"><header><div class="roster-day-date"><strong>${escapeHtml(dayParts.weekday)}</strong><span>${escapeHtml(dayParts.date)}</span></div><button class="small" data-roster-add="${date}">+ Vakt</button></header><div class="roster-day-body">${absenceGroup}${shiftGroups}</div></section>`;
  }).join('');

  const totals=new Map();
  allShifts.forEach(x=>totals.set(x.employee_id,(totals.get(x.employee_id)||0)+rosterDuration(x)));
  const employeeRows=(rosterData.employees||[]).map(employee=>{const planned=totals.get(employee.id)||0,capacity=rosterWeeklyCapacity(employee),difference=capacity===null?null:planned-capacity,over=difference!==null&&difference>.01,hasRate=employee.salary_rate!==null&&employee.salary_rate!==''&&employee.salary_rate!==undefined,hourlyRate=employee.salary_type==='hourly'&&hasRate&&Number.isFinite(Number(employee.salary_rate))?Number(employee.salary_rate):null,cost=hourlyRate===null?null:planned*hourlyRate;return{employee,planned,capacity,difference,over,hourlyRate,cost}});
  const totalHours=employeeRows.reduce((sum,row)=>sum+row.planned,0),totalCost=employeeRows.reduce((sum,row)=>sum+(row.cost||0),0),missingRates=employeeRows.filter(row=>row.planned>0&&row.employee.salary_type==='hourly'&&row.hourlyRate===null).length;
  $('#rosterHours').innerHTML=`<h3>Planlagte timer</h3><div class="roster-hours-table"><table><thead><tr><th>Ansatt</th><th>Planlagt</th><th>Ukenorm</th><th>Avvik</th><th>Timesats</th><th>Est. kostnad</th></tr></thead><tbody>${employeeRows.map(row=>`<tr class="${row.over?'roster-capacity-warning':''}"><td><strong>${escapeHtml(row.employee.full_name)}</strong><small>${row.employee.position_percent==null?'Stillingsgrad mangler':`${Number(row.employee.position_percent).toLocaleString('nb-NO',{maximumFractionDigits:2})} % stilling`}</small></td><td>${hours(row.planned)}</td><td>${row.capacity===null?'–':hours(row.capacity)}</td><td>${row.difference===null?'<span class="status pending">Kontroller stillingsgrad</span>':row.over?`<span class="status roster-warning">+${hours(row.difference)}</span>`:`${row.difference<-.01?'−':''}${hours(Math.abs(row.difference))}`}</td><td>${row.hourlyRate===null?'–':rosterMoney(row.hourlyRate)}</td><td>${row.cost===null?'–':rosterMoney(row.cost)}</td></tr>`).join('')}</tbody></table></div><section class="roster-economy"><div><span>Total timebruk</span><strong>${hours(totalHours)}</strong></div><div><span>Estimert timelønn</span><strong>${rosterMoney(totalCost)}</strong></div><div class="${missingRates?'attention':''}"><span>Mangler timesats</span><strong>${missingRates}</strong></div><p>Ukenorm er beregnet fra 165 timer per måned og registrert stillingsprosent. Kostnaden omfatter bare ansatte med timelønn og inkluderer ikke sosiale kostnader.</p></section>`;
}
function openRosterShift(date,shift=null,presetType='day',presetStart=null,presetEnd=null,presetLabel=null){$('#rosterShiftForm').reset();$('#rosterShiftId').value=shift?.id||'';$('#rosterShiftDate').value=date;$('#rosterShiftHeading').textContent=shift?`Rediger vakt · ${rosterDayLabel(date)}`:`Ny vakt · ${presetLabel||rosterTypes[presetType]} · ${rosterDayLabel(date)}`;$('#rosterShiftEmployee').innerHTML='<option value="">Velg ansatt</option>'+rosterData.employees.map(e=>`<option value="${e.id}">${escapeHtml(e.employee_number)} · ${escapeHtml(e.full_name)}</option>`).join('');$('#rosterShiftEmployee').value=shift?.employee_id||'';$('#rosterShiftType').value=shift?.shift_type||presetType;const defaults=rosterSettings()[$('#rosterShiftType').value];$('#rosterShiftStart').value=String(shift?.start_time||presetStart||defaults[0]).slice(0,5);$('#rosterShiftEnd').value=String(shift?.end_time||presetEnd||defaults[1]).slice(0,5);$('#rosterShiftDialog').showModal()}
$('#rosterShiftType').onchange=()=>{const times=rosterSettings()[$('#rosterShiftType').value];$('#rosterShiftStart').value=String(times[0]).slice(0,5);$('#rosterShiftEnd').value=String(times[1]).slice(0,5)};
