$('#copyPreviousRoster').onclick=async()=>{if(!confirm('Kopiere alle vakter fra forrige uke?'))return;const button=$('#copyPreviousRoster');button.disabled=true;try{const data=await authenticated(`/functions/v1/roster?week=${rosterWeekStart}`,{method:'POST',body:{action:'copy_previous'}});show(`${data.copied} vakter er kopiert.`);await loadRoster()}catch(error){show(error.message)}finally{button.disabled=false}};
