function renderEmployeeRoster(){$('#employeeRosterWeekLabel').textContent=rosterWeekLabel(employeeRosterWeekStart);const shifts=rosterData.shifts||[],days=Array.from({length:7},(_,i)=>rosterAddDays(employeeRosterWeekStart,i));$('#employeeRosterWeek').innerHTML=rosterData.status==='published'?days.map(date=>{const items=shifts.filter(x=>x.work_date===date);return `<section><header><strong>${rosterDayLabel(date)}</strong></header>${items.length?items.map(x=>`<article class="roster-shift ${x.shift_type}"><strong>${rosterShiftLabel(x)}</strong><span>${rosterTime(x.start_time)}–${rosterTime(x.end_time)}${rosterCrossesMidnight(x)?' · neste dag':''}</span></article>`).join(''):'<p class="muted">Fri</p>'}</section>`}).join(''):'<div class="empty">Ingen publisert vaktliste denne uken.</div>'}
